   function newrecaptcha_display_status($output)
   {
      $errors = 0;
      foreach($output as $line)
      {
         $is_error = $line[0];
         if ($is_error)
            $errors++;
         if (is_array($line[1]))
            $msg = array_shift($line[1]);
         else
            $msg = $line[1];
         $msg = ' - <span style="color:'.($is_error?'red':'green').';">'.$msg.'</span>';
         print_description_row($msg);
         if (is_array($line[1]))
         {
            foreach ($line[1] as $msg)
            {
               $msg = ' &nbsp;&nbsp;&nbsp;&nbsp;- <span style="color:'.($is_error?'red':'green').';">'.$msg.'</span>'; 
               print_description_row($msg);
            }
         }
      }
      return $errors;
   }
}
